     1	/**
     2	 * Reconstruct a `(flags, directive)` pair from a stored job meta.cmd.
     3	 *
     4	 * Two cmd shapes (both pre-stripped of bg flags by splitBgArgs):
     5	 *   detached: [interpreter, cli.js?, ...userFlags, '-p', directive]
     6	 *   pty:      [interpreter, cli.js?, '--bg-pty-host', sock, cols, rows,
     7	 *              '--', interpreter, cli.js?, ...userFlags, directive]
     8	 *
     9	 * Detached uses `-p directive` so the marker is unambiguous. Pty uses
    10	 * the directive as a positional (REPL prompt-arg) so we extract the
    11	 * LAST non-flag arg from the inner-ccb tail.
    12	 */
    13	export function extractRespawnArgs(cmd: readonly string[]): {
    14	  flags: string[]
    15	  directive: string
    16	} | null {
    17	  let i = cmd[0]?.endsWith('bun') ? 2 : 1
    18	  let isPty = false
    19	  if (cmd[i] === '--bg-pty-host') {
    20	    isPty = true
    21	    const dashDash = cmd.indexOf('--', i)
    22	    if (dashDash < 0) return null
    23	    i = dashDash + 1
    24	    if (i < cmd.length && cmd[i]?.endsWith('bun')) i += 2
    25	    else i += 1
    26	  }
    27	
    28	  if (!isPty) {
    29	    // detached: -p marker
    30	    const pIdx = cmd.lastIndexOf('-p')
    31	    if (pIdx < i || pIdx === cmd.length - 1) return null
    32	    return {
    33	      flags: [...cmd.slice(i, pIdx)],
    34	      directive: cmd.slice(pIdx + 1).join(' '),
    35	    }
    36	  }
    37	
    38	  // pty: scan inner args, separating flags+values from positional.
    39	  // Reuse splitBgArgs's flag-with-value table: flags like --model
    40	  // consume the next arg as their value rather than treating it as a
    41	  // positional.
    42	  const inner = cmd.slice(i)
    43	  return parseInnerArgs(inner)
    44	}
    45	
    46	/**
    47	 * Same flag-detection rules as bg/argParse.ts splitBgArgs, minus the
    48	 * --bg-* prefix stripping (those don't appear in stored cmds).
    49	 */
    50	function parseInnerArgs(args: readonly string[]): {
    51	  flags: string[]
    52	  directive: string
    53	} | null {
    54	  const FLAGS_WITH_VALUE = new Set([
    55	    '--model',
    56	    '--permission-mode',
    57	    '--session-id',
    58	    '--add-dir',
    59	    '-r',
    60	    '--resume',
    61	    '--max-turns',
    62	    '--cwd',
    63	    '--debug-file',
    64	    '--mcp-config',
    65	    '--append-system-prompt',
    66	    '--strict-mcp-config',
    67	    '--include-partial-messages',
    68	  ])
    69	  const dashDashIdx = args.indexOf('--')
    70	  const before = dashDashIdx >= 0 ? args.slice(0, dashDashIdx) : args
    71	  const after = dashDashIdx >= 0 ? args.slice(dashDashIdx + 1) : []
    72	  const flags: string[] = []
    73	  const positionals: string[] = []
    74	  for (let k = 0; k < before.length; k++) {
    75	    const a = before[k]!
    76	    if (a.startsWith('-')) {
    77	      flags.push(a)
    78	      if (a.includes('=')) continue
    79	      const next = before[k + 1]
    80	      if (next !== undefined && !next.startsWith('-') && FLAGS_WITH_VALUE.has(a)) {
    81	        flags.push(next)
    82	        k++
    83	      }
    84	      continue
    85	    }
    86	    positionals.push(a)
    87	  }
    88	  const directive = [...positionals, ...after].join(' ')
    89	  if (!directive) return null
    90	  return { flags, directive }
    91	}
