export async function cleanupPtyPidBreadcrumbs(
  short: string,
  ptySocket?: string,
): Promise<void> {
  const base = ptySocket ?? getPtySocketPath(short)
  const paths = [
    join(getPtyPidsDir(), `${short}.pid`),
    `${base}.err`,
    `${base}.late`,
    `${base}.exec-exit`,
